package com.melonman106.vbvclient;
import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
public final class VBVCrosshairScreen extends Screen {private final Screen parent;public VBVCrosshairScreen(Screen p){super(Component.literal("Custom Crosshair"));parent=p;}@Override protected void init(){super.init();int cell=18,left=width/2-135,top=55;for(int y=0;y<15;y++)for(int x=0;x<15;x++){final int i=y*15+x;addRenderableWidget(Button.builder(Component.literal(VBVCrosshairConfig.pixels[i]?"■":"·"),b->{VBVCrosshairConfig.pixels[i]=!VBVCrosshairConfig.pixels[i];b.setMessage(Component.literal(VBVCrosshairConfig.pixels[i]?"■":"·"));}).bounds(left+x*cell,top+y*cell,17,17).build());}addRenderableWidget(Button.builder(Component.literal("Enable: "+(VBVCrosshairConfig.enabled?"ON":"OFF")),b->{VBVCrosshairConfig.enabled=!VBVCrosshairConfig.enabled;b.setMessage(Component.literal("Enable: "+(VBVCrosshairConfig.enabled?"ON":"OFF")));}).bounds(width/2-100,top+15*cell+8,200,20).build());addRenderableWidget(Button.builder(Component.literal("Default"),b->{VBVCrosshairConfig.defaultCrosshair();VBVNav.open(new VBVCrosshairScreen(parent));}).bounds(width/2-100,top+15*cell+34,95,20).build());addRenderableWidget(Button.builder(Component.literal("Clear"),b->{VBVCrosshairConfig.clear();VBVNav.open(new VBVCrosshairScreen(parent));}).bounds(width/2+5,top+15*cell+34,95,20).build());addRenderableWidget(Button.builder(Component.literal("Back"),b->VBVNav.open(parent)).bounds(width/2-100,height-30,200,20).build());}
@Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float pt){g.fill(0,0,width,height,0xFF101010);super.extractRenderState(g,mx,my,pt);String t="CUSTOM CROSSHAIR";g.text(font,t,width/2-font.width(t)/2,25,0xFFFFFFFF,true);g.text(font,"Draw your own 15×15 crosshair grid.",width/2-90,42,0xFFAAAAAA,false);}@Override public void onClose(){VBVNav.open(parent);}}
